/**
 * Zarincode local Chart helper (subset of Chart.js API used by the sales dashboard).
 * Ships in-theme so admin charts never depend on a public CDN.
 */
(function (global) {
	'use strict';

	function hexAlpha(color, a) {
		if (!color) { return 'rgba(201,162,39,' + a + ')'; }
		if (color.length === 9) { return color; }
		if (color.charAt(0) === '#' && color.length === 7) {
			var r = parseInt(color.slice(1, 3), 16);
			var g = parseInt(color.slice(3, 5), 16);
			var b = parseInt(color.slice(5, 7), 16);
			return 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')';
		}
		return color;
	}

	function Chart(el, config) {
		this.el = el;
		this.config = config || {};
		this.draw();
	}

	Chart.prototype.draw = function () {
		var canvas = this.el;
		if (!canvas || !canvas.getContext) { return; }
		var ctx = canvas.getContext('2d');
		var type = this.config.type || 'bar';
		var data = this.config.data || {};
		var labels = data.labels || [];
		var ds = (data.datasets && data.datasets[0]) || { data: [] };
		var values = ds.data || [];
		var w = canvas.clientWidth || 640;
		var h = canvas.clientHeight || 280;
		var dpr = window.devicePixelRatio || 1;
		canvas.width = Math.max(1, Math.floor(w * dpr));
		canvas.height = Math.max(1, Math.floor(h * dpr));
		ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
		ctx.clearRect(0, 0, w, h);
		if (!values.length) { return; }
		if (type === 'doughnut') {
			this.doughnut(ctx, w, h, labels, values, ds);
		} else if (type === 'line') {
			this.line(ctx, w, h, labels, values, ds);
		} else {
			this.bar(ctx, w, h, labels, values, ds);
		}
	};

	Chart.prototype.bar = function (ctx, w, h, labels, values, ds) {
		var pad = { t: 16, r: 12, b: 36, l: 44 };
		var max = Math.max.apply(null, values.concat([1]));
		var n = values.length;
		var iw = w - pad.l - pad.r;
		var ih = h - pad.t - pad.b;
		var gap = Math.max(4, iw / n * 0.25);
		var bw = Math.max(4, (iw / n) - gap);
		ctx.strokeStyle = '#e2e8f0';
		ctx.beginPath();
		ctx.moveTo(pad.l, pad.t);
		ctx.lineTo(pad.l, pad.t + ih);
		ctx.lineTo(pad.l + iw, pad.t + ih);
		ctx.stroke();
		values.forEach(function (v, i) {
			var x = pad.l + i * (bw + gap) + gap / 2;
			var bh = (v / max) * ih;
			var y = pad.t + ih - bh;
			ctx.fillStyle = ds.backgroundColor || ds.borderColor || '#C9A227';
			ctx.beginPath();
			if (ctx.roundRect) { ctx.roundRect(x, y, bw, bh, 4); } else { ctx.rect(x, y, bw, bh); }
			ctx.fill();
		});
		this.axisLabels(ctx, w, h, pad, labels);
	};

	Chart.prototype.line = function (ctx, w, h, labels, values, ds) {
		var pad = { t: 16, r: 12, b: 36, l: 44 };
		var max = Math.max.apply(null, values.concat([1]));
		var n = values.length;
		var iw = w - pad.l - pad.r;
		var ih = h - pad.t - pad.b;
		var pts = values.map(function (v, i) {
			return {
				x: pad.l + (n === 1 ? iw / 2 : (i / (n - 1)) * iw),
				y: pad.t + ih - (v / max) * ih
			};
		});
		ctx.strokeStyle = '#e2e8f0';
		ctx.beginPath();
		ctx.moveTo(pad.l, pad.t);
		ctx.lineTo(pad.l, pad.t + ih);
		ctx.lineTo(pad.l + iw, pad.t + ih);
		ctx.stroke();
		ctx.beginPath();
		pts.forEach(function (p, i) {
			if (i === 0) { ctx.moveTo(p.x, p.y); } else { ctx.lineTo(p.x, p.y); }
		});
		ctx.strokeStyle = ds.borderColor || '#2563EB';
		ctx.lineWidth = 2;
		ctx.stroke();
		ctx.lineTo(pts[pts.length - 1].x, pad.t + ih);
		ctx.lineTo(pts[0].x, pad.t + ih);
		ctx.closePath();
		ctx.fillStyle = hexAlpha(ds.borderColor || '#2563EB', 0.15);
		ctx.fill();
		this.axisLabels(ctx, w, h, pad, labels);
	};

	Chart.prototype.doughnut = function (ctx, w, h, labels, values, ds) {
		var cx = w / 2, cy = h / 2 - 8;
		var r = Math.min(w, h) * 0.32;
		var total = values.reduce(function (a, b) { return a + b; }, 0) || 1;
		var colors = ds.backgroundColor || ['#C9A227', '#2563EB', '#16A34A', '#DC2626'];
		var start = -Math.PI / 2;
		values.forEach(function (v, i) {
			var slice = (v / total) * Math.PI * 2;
			ctx.beginPath();
			ctx.moveTo(cx, cy);
			ctx.arc(cx, cy, r, start, start + slice);
			ctx.closePath();
			ctx.fillStyle = colors[i % colors.length];
			ctx.fill();
			start += slice;
		});
		ctx.beginPath();
		ctx.arc(cx, cy, r * 0.55, 0, Math.PI * 2);
		ctx.fillStyle = '#fff';
		ctx.fill();
		ctx.font = '11px sans-serif';
		ctx.textAlign = 'center';
		labels.forEach(function (lab, i) {
			ctx.fillStyle = colors[i % colors.length];
			ctx.fillText(String(lab).slice(0, 18), cx, h - 8 - (labels.length - 1 - i) * 14);
		});
	};

	Chart.prototype.axisLabels = function (ctx, w, h, pad, labels) {
		ctx.fillStyle = '#64748b';
		ctx.font = '10px sans-serif';
		ctx.textAlign = 'center';
		var n = labels.length;
		var step = n > 10 ? Math.ceil(n / 8) : 1;
		labels.forEach(function (lab, i) {
			if (i % step !== 0 && i !== n - 1) { return; }
			var x = pad.l + (n === 1 ? (w - pad.l - pad.r) / 2 : (i / Math.max(1, n - 1)) * (w - pad.l - pad.r));
			ctx.fillText(String(lab).slice(0, 12), x, h - 10);
		});
	};

	global.Chart = Chart;
})(typeof window !== 'undefined' ? window : this);
